from pathlib import Path
import json,hashlib,base64,io,zipfile,html
from PIL import Image
R=Path(__file__).resolve().parents[1]
def sha(b):return hashlib.sha256(b).hexdigest()
def j(p):return json.loads((R/p).read_text('utf-8'))
def graphic(p,caption,kind,crop=None):
 data=(R/p).read_bytes();im=Image.open(io.BytesIO(data));size=im.size
 if crop:
  im=im.crop(crop);buf=io.BytesIO();im.save(buf,format='PNG');display=buf.getvalue();size=im.size
 else:display=data
 return {'source_project_path':p,'source_sha256':sha(data),'kind':kind,'caption':caption,'native_crop_box':crop,'display_size':size,'display_sha256':sha(display),'data_uri':'data:image/png;base64,'+base64.b64encode(display).decode()}

