 records=[{'id':'HOWTO','title':'How to control','source_banks':[116,117],'state':'후보 글자는 관측 경로에서 미참조; 뱅크의 장식은 실제 사용','facts':['일반 안내 selector10 압축 NT1024셀에서 글자 tile90..96은0개, 장식267셀은 사용.','현재047 기준/관측 각4200frames. 공통1658파일·275전체화면 동일.','테두리 tile81 실제읽기16896행·1056프레임과35 actual RGB 확인. 후보 label 읽기는 관측0.'],'limits':['한정된 안내 경로의 결과. 모든 분기·모든 엔진에서의 미사용은 미확정.','원본 유지 중이며 최종 사람 보존 승인 또는 전체 한글화 완료를 뜻하지 않음.'],'evidence_works':[99,100],'images':[0,1],'decision':'pending'},{'id':'PAUSE','title':'PAUSE','source_banks':[120,121],'state':'네 pause 경로와 제한된 폰트 공급을 조사; 표시 소비 미연결','facts':['과거042 네 놀이기구 native pause/resume은 새 글자·CHR를 출력하지 않았음.','현재047/원본 고정 IRQ·animation80쌍·IRQ latch96쌍 및 등록page192 init의 지정 범위에는120/121 없음.','원본2KiB를 보존. 다른 indexed/indirect/computed 공급은 아직 닫지 못했음.'],'limits':['일반 일시정지의 관측을 전역 미사용으로 확대하지 않음.','잠재 그림의 일시정지 번역·최종 보존 승인 미확정.'],'evidence_works':[49,101,102,103],'images':[2,3],'decision':'pending'},{'id':'POW','title':'POW 효과 그림','source_banks':[61],'state':'정적 타격 효과 후보. 같은 뱅크 깃발 소비와 불꽃 후보를 구분','facts':['source61→native3E→OAM83→실제 PPU51520행/805프레임/27 RGB로 깃발은 연결. POW가 아님.','마지막 장면9D..A2는 실제 bank54 불꽃 코드. bank61 가정의 POW 모습과 구분.','선택한 POW 후보 frame18/19/3C/7C 등 실제 표시 호출은 미연결.'],'limits':['초기 티켓seed와 실제 게임오버 경로를 명시. 자연 전체 게임완주 증거 아님.','효과음의 뜻/번역 방향 또는 원문 유지에 대한 사람 결정은 미확정.'],'evidence_works':[96,97,98],'images':[4,5],'decision':'pending'}]
 payload={'work':104,'artifact':'Consumer review supplement, not final release or Cafe article','build':'dialogue_kr_poc_047','ROM_sha256':sha(rom),'CSV_sha256':sha((R/'workspace/translation/text_ja.csv').read_bytes()),'source_sha256':src['sha256'],'human_approved':False,'release_eligible':False,'records':records,'images':images,'limits':['54본문/33그림 기존 사람검토047 kit를 대체하지 않는 소비근거 보충자료','전역corpus·자연전체완주·최종사람검토·PCM청음/실기 미완료','ROM없는 내부검토 자료. 외부게시 및 네이버 카페 완성작업기 아님']}
