 css='body{margin:0;background:#edf1f5;color:#17212b;font-family:Segoe UI,Malgun Gothic,sans-serif;font-size:17px;line-height:1.65}main{max-width:1080px;margin:auto;padding:24px}h1{font-size:30px;line-height:1.3}h2{margin-top:0}header,.candidate{background:white;border-radius:12px;padding:24px;margin-bottom:24px;box-shadow:0 2px 8px #14223212}.state{font-weight:bold;color:#8a4b09}.figures{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0;min-width:0;background:#f2f4f7;border-radius:8px;padding:12px}img{display:block;max-width:100%;height:auto;image-rendering:pixelated;min-height:32px;margin:0 auto;object-fit:contain}figure img{width:100%}figcaption,.small{font-size:14px;color:#4a5662;overflow-wrap:anywhere}label{display:block;margin:16px 0}select,textarea{display:block;width:100%;box-sizing:border-box;font:inherit;padding:9px;border:1px solid #758697;border-radius:5px}button{font:inherit;background:#174a78;color:white;border:0;border-radius:6px;padding:10px 18px;cursor:pointer}.hash{font:13px monospace;overflow-wrap:anywhere}li{padding-bottom:6px}@media(max-width:640px){main{padding:12px}header,.candidate{padding:16px}.figures{grid-template-columns:1fr}h1{font-size:25px}ul{padding-left:22px}}'
 script='''function decisions(){return {build:"dialogue_kr_poc_047",ROM_sha256:"'''+sha(rom)+'''",human_approved:false,release_eligible:false,review_input:Array.from(document.querySelectorAll("select")).map(s=>({id:s.dataset.id,choice:s.value,note:document.querySelector('[data-note="'+s.dataset.id+'"]').value})),notice:"검토 의견 초안. 이 파일만으로 최종 승인/ROM 수정/배포를 실행하지 않습니다."}}document.querySelector("#export").onclick=()=>{const blob=new Blob([JSON.stringify(decisions(),null,2)+"\\n"],{type:"application/json;charset=utf-8"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="TinyToon2_047_consumer_review_input.json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};'''
 page='<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>타이니툰2 047 — 그림 소비 검토 보충자료</title><style>'+css+'</style><main><header><h1>타이니툰2 047<br>남은 그림 소비 검토</h1><p>HOW TO CONTROL·PAUSE·POW의 현재 근거와 미확정 범위를 함께 봅니다. <strong>실제 게임 화면과 정적 설명 그림은 캡션으로 구분했습니다.</strong></p><p>본문54개와 기존 그림33개 검토047 묶음에 추가하는 자료입니다. 원본 그림을 유지하고 있으며 세 항목의 최종 사람 결정은 아직 없습니다.</p><p>완료·전역 미사용·공개판 또는 카페 완성 작업기를 선언하는 자료가 아닙니다. ROM은 포함하지 않습니다.</p><p class="hash">현재 ROM SHA256 '+sha(rom)+'</p><button id="export">검토 의견 JSON 저장</button></header>'+''.join(cards)+'</main><script>'+script+'</script></html>'
 out.mkdir();(out/'review.html').write_text(page,'utf-8');(out/'consumer_records.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n','utf-8');(out/'DECISIONS_PENDING.md').write_text('# 남은 그림의 사람 검토\n\n세 항목의 현재 decision은 모두 pending이며 human_approved/release_eligible은 false다. HTML에서 의견을 선택하고 JSON으로 저장할 수 있지만 자동 승인이나 ROM 변경을 하지 않는다.\n\n'+''.join('## '+r['title']+'\n\n'+r['state']+'\n\n'+'\n'.join('- '+x for x in r['facts']+r['limits'])+'\n\n'for r in records),'utf-8');(out/'README.txt').write_text('review.html을 브라우저로 열어 검토한다. 자체포함6이미지/3후보이며 외부페이지나 ROM이 필요하지 않다. 실제현재047·과거042·원본정적그림/가설조립을 캡션으로 구분했다. 기존 Translation Review047과 Review Patch047은 별도 자료로 보존했다. 이 묶음은 내부 검토 보충자료이며 네이버 카페 완성 작업기/배포판이 아니다.\n','utf-8')
